import{_ as e,o as a,c as o,a2 as d}from"./chunks/framework.BjkiRu3Q.js";const _=JSON.parse('{"title":"Ταυτοποίηση και πρόσβαση εταιρείας","description":"","frontmatter":{},"headers":[],"relativePath":"el/developers/authentication.md","filePath":"el/developers/authentication.md"}'),r={name:"el/developers/authentication.md"};function i(n,t,s,c,l,p){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="ταυτοποιηση-και-προσβαση-εταιρειας" tabindex="-1">Ταυτοποίηση και πρόσβαση εταιρείας <a class="header-anchor" href="#ταυτοποιηση-και-προσβαση-εταιρειας" aria-label="Permalink to &quot;Ταυτοποίηση και πρόσβαση εταιρείας&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Προσχέδιο βάσει πηγαίου κώδικα · v0.7.9. Επιβεβαιώστε διαθεσιμότητα και δικαιώματα στην εγκεκριμένη έκδοση.</p></div><h2 id="συμβαση-api-χειριστη" tabindex="-1">Σύμβαση API χειριστή <a class="header-anchor" href="#συμβαση-api-χειριστη" aria-label="Permalink to &quot;Σύμβαση API χειριστή&quot;">​</a></h2><p>Οι προστατευμένες διαδρομές χειριστή βρίσκονται κάτω από <code>/api/v1</code>. Αποστείλετε έγκυρο bearer access token στο <code>Authorization</code> και το UUID της επιλεγμένης εταιρείας στο <code>X-Company-Id</code>. Ο διακομιστής ελέγχει ανεξάρτητα τη συμμετοχή στην εταιρεία και τα δικαιώματα. Η κεφαλίδα εταιρείας δεν παρέχει από μόνη της πρόσβαση.</p><p>Ο κώδικας χρησιμοποιεί επαλήθευση RS256 JWT. Χρησιμοποιήστε την εγκεκριμένη διαδικασία ταυτοποίησης του περιβάλλοντος. Μην ενσωματώνετε tokens χειριστών σε δημόσιες ιστοσελίδες ή widgets.</p><table tabindex="0"><thead><tr><th>Απόκριση</th><th>Σημασία</th></tr></thead><tbody><tr><td>401</td><td>Απουσία ή μη έγκυρο token</td></tr><tr><td>400</td><td>Απουσία ή μη έγκυρη επιλογή εταιρείας</td></tr><tr><td>403</td><td>Άρνηση πρόσβασης εταιρείας ή δικαιώματος</td></tr><tr><td>503</td><td>Μη διαθέσιμη υπηρεσία εξουσιοδότησης</td></tr></tbody></table><p>Σε περίπτωση άρνησης επιλύστε το πρόβλημα πρόσβασης, αντί να αντικαταστήσετε το ID εταιρείας. Χρησιμοποιείτε μόνο συνθετικά δεδομένα στις δοκιμές.</p><p>Δείτε <a href="/el/developers/permissions.html">Ρόλοι και δικαιώματα</a>.</p><p>Για διαπιστευτήρια παρόχων δείτε <a href="/el/integrations/api-keys.html">Κλειδιά API και ασφαλής ρύθμιση</a>.</p>',9)])])}const m=e(r,[["render",i]]);export{_ as __pageData,m as default};
